import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0004: Why Resource + Dependency Graph","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0004-why-resource-dependency-graph.md","filePath":"adr/ADR-0004-why-resource-dependency-graph.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0004-why-resource-dependency-graph.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0004-why-resource-dependency-graph" tabindex="-1">ADR-0004: Why Resource + Dependency Graph <a class="header-anchor" href="#adr-0004-why-resource-dependency-graph" aria-label="Permalink to “ADR-0004: Why Resource + Dependency Graph”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/resources.md §3, ADR-0005</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Correct handling of real failures is determined by topology: when the database dies, restarting the application is meaningless; when the proxy breaks, the Tunnel&#39;s &quot;recovery&quot; just spins. Resources are not a flat list of monitoring items — they form a directed dependency graph.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>Resource</code> describes the object (probe, health policy, recovery policy); <code>Dependency</code> describes preconditions (required/optional/conditional + <code>HealthCondition</code>). The configuration loader builds both into a <code>DependencyGraph</code>: dangling references, duplicate IDs, impossible conditions, and cycles are all reported with concrete field paths at load time — startup is rejected instead of deadlocking at runtime.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Flat resource list</strong>: recovery has no ordering semantics; &quot;fix db before app&quot; cannot be expressed.</li><li><strong>Implicit probe order (by config order)</strong>: order is coincidental, not semantic; changing the config order changes the behavior.</li><li><strong>Runtime dynamic dependency discovery</strong>: no validation timing; the later an error is found, the costlier it is.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: recovery order is derivable (topological sort); all structural errors rejected at load time in one pass; conditional dependencies (<code>conditional_on</code>) and alternative groups (<code>alternative_groups</code>) express redundancy and degradation semantics. Cons: modeling learning curve; configuration errors surface at startup (a feature, not a defect).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>graph.rs cycle detection returns the concrete cycle path (ADR-0014).</li><li>The engine&#39;s waiter deduplication (§3.6) builds on graph semantics: all waiters on the same dependency share one recovery result.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};